INSERT INTO rukn_ai.knowledge_documents(title,category,content,source_type,status,created_by)
VALUES
('تعريف ركن للأعمال الفنية','تعريف بالمشروع','ركن للأعمال الفنية مشروع لتصميم وتصنيع وتنفيذ أعمال فنية وديكورية وهندسية حسب الطلب، ويحوّل أفكار العملاء إلى منتجات مخصصة باستخدام الحرفة اليدوية والتقنيات الحديثة. شعار المشروع: يدك تصنع أفكارك.','project_profile','pending','initial_setup'),
('خدمات النجارة والأثاث والديكور','خدمات','تشمل خدمات ركن الأعمال الخشبية والأثاث والمطابخ والديكور والقطع المصممة حسب الطلب، مع إمكانية تنفيذ الأعمال والصيانة والتشطيبات وفق مواصفات العميل.','project_profile','pending','initial_setup'),
('خدمات CNC والليزر والتصنيع الرقمي','معدات وتقنيات','يقدم ركن خدمات التصميم والتصنيع باستخدام CNC والراوتر والليزر، لإنتاج اللوحات والقطع الزخرفية والهدايا والمنتجات المخصصة وفق ملف التصميم والخامة والمقاسات.','project_profile','pending','initial_setup'),
('التصميم والطباعة ثلاثية الأبعاد','خدمات','تشمل أعمال ركن التصميم ثلاثي الأبعاد وإعداد المجسمات والنماذج والطباعة ثلاثية الأبعاد، مع مراعاة الغرض من القطعة والخامة وطريقة التصنيع.','project_profile','pending','initial_setup'),
('الدروع والهدايا والإعلانات','خدمات','ينفذ ركن الدروع والميداليات والتذكارات والهدايا والستاندات واللافتات والأعمال الإعلانية والتغليف والمنتجات المخصصة للأفراد والمؤسسات والفعاليات.','project_profile','pending','initial_setup'),
('الخامات المستخدمة في ركن','خامات','تشمل الخامات التي يمكن أن يعمل بها ركن الخشب والبلاستيك وPVC والزجاج والورق والفلين والحديد والألمنيوم والنحاس. يجب اعتماد أسعار كل خامة ومواصفاتها من بيانات فعلية قبل استخدامها في التسعير.','project_profile','pending','initial_setup');
